theorem isCyclicVertex_image (P : FiniteConvexPolytope A) (g : A ≃ᵃⁱ[ℝ] A)
    (hg : (⇑g) '' P.toSet = P.toSet) {v : A} {q : ℕ}
    (hv : P.IsCyclicVertex v q) : P.IsCyclicVertex (g v) q

theorem isRegularFacet_image (P : FiniteConvexPolytope A) (g : A ≃ᵃⁱ[ℝ] A)
    (hg : (⇑g) '' P.toSet = P.toSet) {F : Set A} {p : ℕ} {ℓ : ℝ}
    (hF : P.IsRegularFacet F p ℓ) : P.IsRegularFacet ((⇑g) '' F) p ℓ

theorem classe_mem_quoziente (d : ℕ) (P : regularPolytopes d) :
    classe d P ∈ {S : Set (regularPolytopes d) |
      ∃ P', S = {Q : regularPolytopes d | regularSimilar d P' Q}}

theorem similar_of_classe_eq {d : ℕ} {P Q : regularPolytopes d}
    (h : classe d P = classe d Q) :
    ConvexPolytope.Similar (P : ConvexPolytope d) (Q : ConvexPolytope d)

theorem classeSim_mem_quoziente (d : ℕ) (P : regularPolytopes d) :
    classeSim d P ∈ {S : Set (regularPolytopes d) |
      ∃ P', S = {Q : regularPolytopes d | regularSimilar d P' Q}}

theorem basis_mem_iperCoordSpan {d : ℕ} {A : Finset (Fin d)} {i : Fin d}
    (hi : i ∈ A) :
    (EuclideanSpace.basisFun (Fin d) ℝ) i ∈ iperCoordSpan A

theorem ipercubo_face_free_card (d : ℕ) (hd : 1 ≤ d) {f : Set (E d)}
    (hf : (ipercubo d hd).IsFace f) {s : Fin d → Bool} (hs : vertIper s ∈ f) :
    (iperFaceFree f s).card = faceDim f

theorem ipercubo_face_mix (d : ℕ) (hd : 1 ≤ d) {f : Set (E d)}
    (hf : (ipercubo d hd).IsFace f) {a b : Fin d → Bool}
    (haF : vertIper a ∈ f) (hbF : vertIper b ∈ f) (m : Fin d → Bool) :
    vertIper (boolMix a b m) ∈ f

theorem ipercubo_face_vectorSpan (d : ℕ) (hd : 1 ≤ d) {f : Set (E d)}
    (hf : (ipercubo d hd).IsFace f) {s : Fin d → Bool} (hs : vertIper s ∈ f) :
    vectorSpan ℝ f = iperCoordSpan (iperFaceFree f s)

theorem ipercubo_face_vertices_nonempty (d : ℕ) (hd : 1 ≤ d) {f : Set (E d)}
    (hf : (ipercubo d hd).IsFace f) :
    ((ipercubo d hd).vertices.filter (· ∈ f)).Nonempty

theorem segnoPerm_mem_verticiIper (d : ℕ) (σ : Equiv.Perm (Fin d))
    (ε : Fin d → ({-1, 1} : Set ℝ)) {v : E d}
